<?php
declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/batches.php';$current=tuman_require_role('TEACHER');$db=tuman_database();$id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id||!($batch=tuman_teacher_batch($db,$current['id'],(int)$id))){http_response_code(404);exit('Batch unavailable.');}$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!tuman_csrf_is_valid($_POST['csrf_token']??null))throw new InvalidArgumentException('Your request could not be verified.');$assignment=filter_var($_POST['assignment_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$assignment)throw new InvalidArgumentException('Choose a student.');tuman_add_batch_member($db,$current['id'],(int)$id,(int)$assignment,trim((string)($_POST['enrolled_on']??'')));header('Location: /Tuman/teacher/batch-view.php?id='.$id);exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to add the student right now.';}}$members=tuman_batch_members($db,$current['id'],(int)$id);$students=array_filter(tuman_teacher_students($db,$current['id']),fn($s)=>$s['assignment_status']==='ACTIVE');$billingRules=tuman_batch_billing_rules($db,$current['id'],(int)$id);tuman_teacher_page_start('Manage batch');
?>
<h1><?=htmlspecialchars($batch['batch_name'],ENT_QUOTES,'UTF-8')?></h1><p><a class="button" href="/Tuman/teacher/batch-edit.php?id=<?=(int)$id?>">Edit batch details</a> <a class="button" href="/Tuman/teacher/batch-billing-create.php?id=<?=(int)$id?>">Add billing option</a> <a class="button" href="/Tuman/teacher/batch-invoice-create.php?id=<?=(int)$id?>">Generate draft invoices</a></p><h2>Billing options</h2><?php if($billingRules===[]):?><p>No billing options have been added.</p><?php else:?><table><thead><tr><th>Type</th><th>Charge</th><th>Status</th></tr></thead><tbody><?php foreach($billingRules as $rule):?><tr><td><?=htmlspecialchars(ucwords(strtolower(str_replace('_',' ',$rule['billing_mode']))),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(tuman_currency_amount_label($rule['charge'],$rule['currency_code']),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($rule['status'],ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;?></tbody></table><?php endif;?><h2>Batch details</h2><?php foreach(['objective'=>'Objective','teacher_responsibility'=>"Teacher's responsibility",'student_responsibility'=>"Student's responsibility",'batch_terms'=>'Batch terms'] as $field=>$label):?><p><strong><?=$label?>:</strong> <?=($batch[$field]??'')===''?'—':nl2br(htmlspecialchars($batch[$field],ENT_QUOTES,'UTF-8'))?></p><?php endforeach;?><h2>Add an existing student</h2><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8')?>"><p><label>Student <select name="assignment_id" required><option value="">Choose student</option><?php foreach($students as $student):?><option value="<?=(int)$student['assignment_id']?>"><?=htmlspecialchars(trim($student['first_name'].' '.($student['last_name']??'')),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label> <label>Enrolled on <input type="date" name="enrolled_on" value="<?=gmdate('Y-m-d')?>" required></label> <button>Add student</button></p></form><p><a href="/Tuman/teacher/batch-student-create.php?id=<?=(int)$id?>">Enrol a new student directly into this batch</a></p><h2>Members</h2><table><thead><tr><th>Student</th><th>Enrolled</th><th>Status</th></tr></thead><tbody><?php foreach($members as $member):?><tr><td><?=htmlspecialchars(trim($member['first_name'].' '.($member['last_name']??'')),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($member['enrolled_on'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($member['status'],ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;?></tbody></table><p><a href="/Tuman/teacher/batches.php">Back to batches</a></p><?php tuman_teacher_page_end(); ?>
